using SqlExpert.Core.Models;

namespace SqlExpert.Core.Explorer;

/// <summary>
/// Resource keys of the vector icons (SqlExpert.App/Themes/Icons.xaml, generated by tools/icons/generate_icons.py).
/// The same key is used on the Database Explorer folder, on each object under it and on the Windows-bar tab
/// of the object's editor, so one object type always looks the same.
/// </summary>
public static class ObjectIcons
{
    public const string Prefix = "Icon.";

    /// <summary>Registered database that is not connected.</summary>
    public const string DatabaseRegistration = Prefix + "DatabaseRegistration";
    /// <summary>Registered database that is connected.</summary>
    public const string DatabaseRegistrationConnected = Prefix + "DatabaseRegistrationConnected";
    /// <summary>A database of the connected server.</summary>
    public const string Database = Prefix + "Database";
    /// <summary>SQL Editor document.</summary>
    public const string SqlEditor = Prefix + "SqlEditor";

    /// <summary>Icon of a registration node in the Explorer.</summary>
    public static string Registration(bool connected) => connected ? DatabaseRegistrationConnected : DatabaseRegistration;

    /// <summary>Icon of a folder / object node of <paramref name="kind"/> (and of its editor tab).</summary>
    public static string For(ObjectKind kind) => kind switch
    {
        ObjectKind.Database => Database,
        _ => Prefix + kind
    };

    /// <summary>Every key the application asks for (the audit test checks each one exists).</summary>
    public static IReadOnlyList<string> AllKeys() =>
        new[] { DatabaseRegistration, DatabaseRegistrationConnected, Database, SqlEditor }
            .Concat(Enum.GetValues<ObjectKind>().Select(For))
            .Distinct(StringComparer.Ordinal)
            .ToList();
}
